\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amssymb}
\usepackage{booktabs}
\newcommand{\twh}{\ensuremath{\mathrm{TWh}}}

\title{Electricity Generation and Industrial Output:
Evidence from Regional Panels, 2000--2024}
\author{N.~Beaumont and Y.~Karimova}
\date{August 2026}

\begin{document}
\maketitle

% referee 2 asked about units; keep \twh rather than siunitx for this revision
\section{Stylised Facts}
Regional electricity generation rose from 214 \twh\ in 2000 to
389 \twh\ in 2024, with the fastest growth in the coastal regions.
Peak demand tracked generation closely, reaching 61 \twh\ of
annualised consumption in the final sample year.

\section{Data}
We combine the system operator's generation ledger, reported in
\twh, with the statistical office's regional accounts.
Both series are deflated and seasonally adjusted where applicable.

\section{Discussion}
Each additional \twh\ of annual generation per region is associated
with a 0.14 percent increase in industrial gross value added,
though the estimate is imprecise for the smallest regions.
\end{document}

